39	impl InterpolatedStringLayout {
40	    // Heuristic: Allow breaking the f/t-string expressions across multiple lines
41	    // only if there already is at least one multiline expression. This puts the
42	    // control in the hands of the user to decide if they want to break the
43	    // f/t-string expressions across multiple lines or not. This is similar to
44	    // how Prettier does it for template literals in JavaScript.
45	    //
46	    // If it's single quoted f-string and it contains a multiline expression, then we
47	    // assume that the target version of Python supports it (3.12+). If there are comments
48	    // used in any of the expression of the f-string, then it's always going to be multiline
49	    // and we assume that the target version of Python supports it (3.12+).
50	    //
51	    // Reference: https://prettier.io/docs/en/next/rationale.html#template-literals
52	    pub(crate) fn from_interpolated_string_elements(
53	        elements: &InterpolatedStringElements,
54	        source: &str,
55	    ) -> Self {
56	        if elements
57	            .interpolations()
58	            .any(|expr| source.contains_line_break(expr.range()))
