428	/// Ensure that formatting doesn't change the AST and doesn't introduce any new unsupported syntax errors.
429	///
430	/// Like Black, there are a few exceptions to this "invariant" which are encoded in
431	/// [`NormalizedMod`] and related structs. Namely, formatting can change indentation within strings,
432	/// and can also flatten tuples within `del` statements.
433	///
434	/// Returns any new [`UnsupportedSyntaxError`]s in the formatted code as [`Diagnostic`]s for
435	/// snapshotting.
436	///
437	/// As noted in the sub-diagnostic message, new syntax errors should only be accepted when they are
438	/// the result of an existing syntax error in the input. For example, the formatter knows that
439	/// escapes in f-strings are only allowed after Python 3.12, so it can replace escaped quotes with
440	/// reused outer quote characters, which are also valid after 3.12, even if the configured Python
441	/// version is lower. Such cases disrupt the fingerprint filter because the syntax error, and thus
442	/// its fingerprint, is different from the input syntax error. More typical cases like using a
443	/// t-string before 3.14 will be filtered out and not included in snapshots.
444	fn ensure_unchanged_ast(
445	    unformatted_code: &str,
446	    formatted_code: &str,
447	    options: &PyFormatOptions,
448	    input_path: &Utf8Path,
449	) -> Vec<Diagnostic> {
450	    let source_type = options.source_type();
451	
452	    // Parse the unformatted code.
453	    let unformatted_parsed = parse(
454	        unformatted_code,
455	        ParseOptions::from(source_type).with_target_version(options.target_version()),
456	    )
457	    .expect("Unformatted code to be valid syntax");
458	
459	    let unformatted_unsupported_syntax_errors =
460	        collect_unsupported_syntax_errors(&unformatted_parsed);
461	    let mut unformatted_ast = unformatted_parsed.into_syntax();
462	
463	    Normalizer.visit_module(&mut unformatted_ast);
464	    let unformatted_ast = ComparableMod::from(&unformatted_ast);
465	
466	    // Parse the formatted code.
467	    let formatted_parsed = parse(
468	        formatted_code,
469	        ParseOptions::from(source_type).with_target_version(options.target_version()),
470	    )
471	    .expect("Formatted code to be valid syntax");
472	
473	    // Assert that there are no new unsupported syntax errors
474	    let mut formatted_unsupported_syntax_errors =
475	        collect_unsupported_syntax_errors(&formatted_parsed);
476	
477	    formatted_unsupported_syntax_errors
478	        .retain(|fingerprint, _| !unformatted_unsupported_syntax_errors.contains_key(fingerprint));
479	
480	    // Sort the errors by location to ensure the snapshot output is stable.
481	    let mut formatted_unsupported_syntax_errors = formatted_unsupported_syntax_errors
482	        .into_values()
483	        .collect::<Vec<_>>();
484	    formatted_unsupported_syntax_errors
485	        .sort_by_key(|error| (error.range().start(), error.range().end()));
486	
487	    let file = SourceFileBuilder::new(input_path.file_name().unwrap(), formatted_code).finish();
488	    let diagnostics = formatted_unsupported_syntax_errors
489	        .iter()
490	        .map(|error| {
491	            let mut diag = Diagnostic::new(DiagnosticId::InvalidSyntax, Severity::Error, error);
492	            let span = Span::from(file.clone()).with_range(error.range());
493	            diag.annotate(Annotation::primary(span));
494	            let sub = SubDiagnostic::new(
495	                SubDiagnosticSeverity::Warning,
496	                "Only accept new syntax errors if they are also present in the input. \
497	                    The formatter should not introduce syntax errors.",
498	            );
499	            diag.sub(sub);
500	            diag
501	        })
502	        .collect::<Vec<_>>();
503	
504	    let mut formatted_ast = formatted_parsed.into_syntax();
505	    Normalizer.visit_module(&mut formatted_ast);
506	    let formatted_ast = ComparableMod::from(&formatted_ast);
507	
508	    if formatted_ast != unformatted_ast {
509	        let diff = TextDiff::from_lines(
510	            &format!("{unformatted_ast:#?}"),
511	            &format!("{formatted_ast:#?}"),
512	        )
513	        .unified_diff()
514	        .header("Unformatted", "Formatted")
515	        .to_string();
516	        panic!(
517	            r#"Reformatting the unformatted code of {input_path} resulted in AST changes.
518	---
519	{diff}
520	"#,
521	        );
522	    }
523	
524	    diagnostics
525	}
