598	/// A visitor to collect a sequence of node IDs for fingerprinting [`UnsupportedSyntaxError`]s.
599	///
600	/// It visits each statement in the AST in source order and saves its range. The index of the node
601	/// enclosing a syntax error's range can then be retrieved with the `node_id` method. This `node_id`
602	/// should be stable across formatting runs since the formatter won't add or remove statements.
603	struct StmtVisitor {
604	    nodes: Vec<TextRange>,
605	}
606	
607	impl StmtVisitor {
608	    fn new(parsed: &Parsed<Mod>) -> Self {
609	        let mut visitor = Self { nodes: Vec::new() };
610	        visitor.visit_mod(parsed.syntax());
611	        visitor
612	    }
613	
614	    /// Return the index of the statement node that contains `range`.
615	    fn node_id(&self, range: TextRange) -> usize {
616	        self.nodes
617	            .iter()
618	            .enumerate()
619	            .filter(|(_, node)| node.contains_range(range))
620	            .min_by_key(|(_, node)| node.len())
621	            .expect("Expected an enclosing node in the AST")
622	            .0
623	    }
624	}
625	
626	impl<'a> SourceOrderVisitor<'a> for StmtVisitor {
627	    fn visit_stmt(&mut self, stmt: &'a ruff_python_ast::Stmt) {
628	        self.nodes.push(stmt.range());
629	        ruff_python_ast::visitor::source_order::walk_stmt(self, stmt);
630	    }
631	}
632	
633	/// Collects the unsupported syntax errors and assigns a unique hash to each error.
634	fn collect_unsupported_syntax_errors(
635	    parsed: &Parsed<Mod>,
636	) -> FxHashMap<u64, UnsupportedSyntaxError> {
637	    let mut collected = FxHashMap::default();
638	
639	    if parsed.unsupported_syntax_errors().is_empty() {
640	        return collected;
641	    }
642	
643	    let visitor = StmtVisitor::new(parsed);
644	
645	    for error in parsed.unsupported_syntax_errors() {
646	        let node_id = visitor.node_id(error.range);
647	        let mut error_fingerprint = fingerprint_unsupported_syntax_error(error, node_id, 0);
648	
649	        // Make sure that we do not get a fingerprint that is already in use
650	        // by adding in the previously generated one.
651	        loop {
652	            match collected.entry(error_fingerprint) {
653	                Entry::Occupied(_) => {
654	                    error_fingerprint =
655	                        fingerprint_unsupported_syntax_error(error, node_id, error_fingerprint);
656	                }
657	                Entry::Vacant(entry) => {
658	                    entry.insert(error.clone());
659	                    break;
660	                }
661	            }
662	        }
663	    }
664	
665	    collected
666	}
